package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.net.*;
import java.net.http.*;
import java.nio.file.Path;

final class ScimBrowserAcceptance {
 static HttpResponse<byte[]> send(BrowserTest h,String method,String path,String token,Object value)throws Exception {var request=HttpRequest.newBuilder(URI.create(h.base()+path)).header("Authorization","Bearer "+token).header("Content-Type","application/scim+json").method(method,HttpRequest.BodyPublishers.ofByteArray(JSON.writeValueAsBytes(value))).build();return HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofByteArray());}
 static void run(BrowserTest h)throws Exception {
  String group=ScimAcceptance.group(h.store),name="DirectoryBrowser"+id();
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var worker=browser.newContext()) {
   var page=admin.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Directory provisioning").setExact(true)).press("Enter");page.getByLabel("Directory name").fill("Corporate directory <script>");page.getByLabel("Mapped account role").selectOption("agent");page.getByLabel("Existing group IDs, separated by spaces").fill(group);ServiceOutagesBrowserAcceptance.click(page,"Create directory connection");assertThat(page.locator("main")).containsText("Corporate directory <script>");String token=page.getByLabel("Directory bearer credential").inputValue(),url=page.locator("article").filter(new Locator.FilterOptions().setHasText("Corporate directory <script>")).getByLabel("Users endpoint").inputValue();assertThat(page.locator("main script")).hasCount(0);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/directory-credential-light.png")).setFullPage(true));ServiceOutagesBrowserAcceptance.click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertEquals(false,page.evaluate("Array.from(document.querySelectorAll('main .panel')).some(p=>p.scrollWidth>p.clientWidth+1)"));page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/directory-credential-dark.png")).setFullPage(true));
   var response=send(h,"POST",url,token,ScimAcceptance.user(name,"browser-employee",true));assertEquals(201,response.statusCode(),new String(response.body()));String target=object(JSON.readValue(response.body(),Object.class)).get("id").toString();page.navigate(h.base()+"/admin/accounts/"+target);page.getByLabel("Your administrator password").fill(WorkflowSupport.PASSWORD);ServiceOutagesBrowserAcceptance.click(page,"Create recovery link");String reset=page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Password recovery link").setExact(true)).getAttribute("href");var person=worker.newPage();person.navigate(h.base()+reset);person.getByLabel("New password").fill(WorkflowSupport.PASSWORD);ServiceOutagesBrowserAcceptance.click(person,"Reset password");h.login(person,name);person.navigate(h.base()+"/account");assertThat(person.locator("main")).containsText("Account");assertEquals(200,send(h,"PATCH",url+"/"+target,token,ScimAcceptance.patch(false)).statusCode());person.navigate(h.base()+"/account");person.waitForURL(h.base()+"/login");
   page.navigate(h.base()+"/admin/directories");assertThat(page.getByLabel("Directory bearer credential")).hasCount(0);var source=page.locator("article").filter(new Locator.FilterOptions().setHasText("Corporate directory <script>"));source.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Rotate and authorize credential")).click();String next=page.getByLabel("Directory bearer credential").inputValue();assertNotEquals(token,next);assertEquals(401,send(h,"PATCH",url+"/"+target,token,ScimAcceptance.patch(true)).statusCode());assertEquals(200,send(h,"PATCH",url+"/"+target,next,ScimAcceptance.patch(true)).statusCode());source=page.locator("article").filter(new Locator.FilterOptions().setHasText("Corporate directory <script>"));source.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Disable directory connection")).click();assertThat(page.locator("main")).containsText("This directory connection is disabled");assertEquals(401,send(h,"PATCH",url+"/"+target,next,ScimAcceptance.patch(false)).statusCode());h.login(person,name);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/directory-disabled-dark.png")).setFullPage(true));
   page.getByLabel("Directory name").fill("Empty mapping directory");page.getByLabel("Mapped account role").selectOption("reader");ServiceOutagesBrowserAcceptance.click(page,"Create directory connection");assertThat(page.locator("main")).containsText("Empty mapping directory");
  }
 }
}
